"""1987 Constitution, Articles I, II and IV to XVIII: study notes in our own words, merged into data/notes/const1987.json.
Each note lists the ages, terms, periods and votes it states ('chk'); the script fails if one is not in the verbatim text.
"""
import json

SITE = '/home/claude/site/data'
N = {}


def n(pid, x, k=None, t=None, d=None, chk=()):
    e = {'x': x}
    if k: e['k'] = k
    if t: e['t'] = t
    if d: e['d'] = [{'n': a, 'c': b, 'h': c, 'r': r} for a, b, c, r in d]
    N[pid] = (e, chk)


# Article I and II
n('art-i', 'The national territory: the Philippine archipelago, with all the islands and waters embraced in it, and all other territories over which the Philippines has sovereignty or jurisdiction — its land, sea and air, seabed, subsoil and insular shelves. The waters around, between and connecting the islands are internal waters.',
  t=['The archipelagic doctrine: the islands and the waters between them form one unit.', 'RA 9522 (baselines law) was upheld in Magallona v. Ermita (2011): baselines are a tool to measure maritime zones under UNCLOS, not a way to give up territory.'], chk=['archipelago'])
n('art-ii-sec-1', 'The Philippines is a democratic and republican State. Sovereignty resides in the people and all government authority emanates from them.')
n('art-ii-sec-2', 'The Philippines renounces war as an instrument of national policy, adopts the generally accepted principles of international law as part of the law of the land (incorporation), and adheres to peace, equality, justice, freedom, cooperation and amity with all nations.',
  t=['Incorporation makes customary international law part of domestic law without any legislative act; treaties need Senate concurrence (Art. VII, Sec. 21).'])
n('art-ii-sec-3', 'Civilian authority is, at all times, supreme over the military. The armed forces protect the people and the State; their goal is to secure the sovereignty of the State and the integrity of the national territory.')
n('art-ii-sec-6', 'The separation of Church and State shall be inviolable.', t=['Read with Art. III, Sec. 5 (non-establishment and free exercise) and Art. VI, Sec. 29(2) (no public money for religion).'])
n('art-ii-sec-12', 'The State recognizes the sanctity of family life, protects the life of the mother and the life of the unborn from conception, and recognizes the primary right and duty of parents to rear the youth.',
  d=[('Imbong v. Ochoa', 'G.R. No. 204819, April 8, 2014', 'The Reproductive Health Law was upheld in the main, but provisions that compelled conscientious objectors to refer patients, punished them, or dispensed with spousal or parental consent were struck down. Life begins at fertilization.', 'The leading case on this section.')])
n('art-ii-sec-16', 'The State shall protect and advance the right of the people to a balanced and healthful ecology in accord with the rhythm and harmony of nature.',
  t=['Unlike most of Article II, this right is self-executing.'],
  d=[('Oposa v. Factoran', 'G.R. No. 101083, July 30, 1993', 'Minors, for themselves and for generations yet unborn, had standing to sue to stop timber license agreements: the right to a balanced and healthful ecology is enforceable even without an implementing law (intergenerational responsibility).', 'Self-executing environmental right.')])
n('art-ii-sec-26', 'The State guarantees equal access to opportunities for public service, and prohibits political dynasties as may be defined by law.',
  t=['Not self-executing: there is no constitutional right to run for office, and the ban on political dynasties needs a law defining them (Pamatong v. COMELEC, 2004).'])
n('art-ii-sec-28', 'The State adopts and implements a policy of full public disclosure of all its transactions involving public interest, subject to reasonable conditions prescribed by law.', t=['Read with the right to information, Art. III, Sec. 7.'])

# Article IV — Citizenship
n('art-iv-sec-1', 'Citizens of the Philippines are: those who were citizens when the Constitution was adopted; those whose fathers or mothers are citizens; those born before January 17, 1973 of Filipino mothers who elect Philippine citizenship upon reaching majority; and those naturalized in accordance with law.',
  t=['The Philippines follows jus sanguinis (blood), not jus soli (place of birth).'])
n('art-iv-sec-2', 'Natural-born citizens are those who are citizens from birth without having to perform any act to acquire or perfect their citizenship. Those who elect citizenship under Section 1(3) are deemed natural-born.',
  d=[('Poe-Llamanzares v. COMELEC', 'G.R. No. 221697, March 8, 2016', 'A foundling is presumed to be a natural-born citizen, given the high probability that her parents are Filipino and the generally accepted principles of international law.', 'Foundlings and natural-born status.'),
     ('Bengson III v. HRET', 'G.R. No. 142840, May 7, 2001', 'A natural-born citizen who lost citizenship and later reacquired it by repatriation recovers his original status as natural-born.', 'Effect of repatriation.')])
n('art-iv-sec-3', 'Philippine citizenship may be lost or reacquired in the manner provided by law.', t=['RA 9225 (2003) lets natural-born Filipinos who became foreign citizens reacquire or retain Philippine citizenship by taking an oath, so that dual citizenship results.'])
n('art-iv-sec-4', 'Citizens who marry aliens keep their citizenship, unless by their act or omission they are deemed, under the law, to have renounced it.')
n('art-iv-sec-5', 'Dual allegiance of citizens is inimical to the national interest and shall be dealt with by law.', t=['Dual citizenship (an involuntary result of laws of two states) differs from dual allegiance (a person’s own act of loyalty to two states); only dual allegiance is prohibited (Mercado v. Manzano, 1999).'])

# Article V
n('art-v-sec-1', 'Suffrage may be exercised by citizens not otherwise disqualified by law, at least eighteen years of age, who have resided in the Philippines for at least one year and in the place where they propose to vote for at least six months immediately before the election. No literacy, property or other substantive requirement may be imposed.',
  t=['Registration is a procedural requirement, not a “substantive” one, so it is valid (Kabataan Party-List v. COMELEC, 2015, on biometrics).'], chk=['eighteen years', 'one year', 'six months'])

# Article VI — Legislative
n('art-vi-sec-1', 'Legislative power is vested in Congress (a Senate and a House of Representatives), except to the extent reserved to the people by initiative and referendum.', t=['Non-delegation: Congress may delegate only if the law is complete and sets a sufficient standard.'])
n('art-vi-sec-3', 'A Senator must be a natural-born citizen, at least thirty-five years old on election day, able to read and write, a registered voter, and a resident of the Philippines for at least two years immediately before the election.', chk=['thirty-five years', 'two years'])
n('art-vi-sec-4', 'Senators serve six-year terms and may not serve more than two consecutive terms; voluntary renunciation is not an interruption.', chk=['six years', 'two consecutive terms'])
n('art-vi-sec-5', 'The House has not more than 250 members unless the law provides otherwise, elected by district, plus party-list representatives who make up twenty percent of the total.',
  d=[('BANAT v. COMELEC', 'G.R. No. 179271, April 21, 2009', 'The two-percent threshold cannot bar parties from additional seats when the twenty-percent allocation is not filled; the Court laid down the formula for allocating party-list seats.', 'Party-list seat allocation.'),
     ('Atong Paglaum v. COMELEC', 'G.R. No. 203766, April 2, 2013', 'Party-list groups need not represent marginalized sectors; national and regional parties may participate. New parameters were set.', 'Who may join the party-list system.')])
n('art-vi-sec-6', 'A Member of the House must be a natural-born citizen, at least twenty-five years old on election day, able to read and write, a registered voter in the district (except party-list), and a resident of it for at least one year immediately before the election.', chk=['twenty-five years', 'one year'])
n('art-vi-sec-7', 'Members of the House serve three-year terms and may not serve more than three consecutive terms.', chk=['three years', 'three consecutive terms'])
n('art-vi-sec-11', 'Parliamentary immunity: members are privileged from arrest while Congress is in session for offenses punishable by not more than six years’ imprisonment, and may not be questioned elsewhere for any speech or debate in Congress or its committees.',
  t=['The privilege from arrest does not cover offenses punishable by more than six years.', 'Speech and debate immunity protects against suits elsewhere, not against discipline by the member’s own chamber.'], chk=['six years'])
n('art-vi-sec-13', 'Incompatible and forbidden offices: a member may not hold any other government office (including in GOCCs) during his term without forfeiting his seat, nor be appointed to any office created, or whose pay was increased, during the term for which he was elected.')
n('art-vi-sec-16', 'Each House elects its officers, determines its rules, and may punish members for disorderly behavior; suspension (not over sixty days) or expulsion needs the concurrence of two-thirds of all its members. A majority of each House is a quorum.', chk=['sixty days', 'two-thirds'])
n('art-vi-sec-17', 'Each House has an Electoral Tribunal of nine: three Supreme Court Justices and six members of the House chosen on proportional representation. It is the sole judge of contests on the election, returns and qualifications of its members.', t=['The tribunal’s jurisdiction begins once the winner has been proclaimed, has taken his oath and assumed office.'])
n('art-vi-sec-21', 'Congress or its committees may conduct inquiries in aid of legislation under duly published rules; the rights of persons appearing in or affected by them shall be respected.',
  d=[('Senate v. Ermita', 'G.R. No. 169777, April 20, 2006', 'An executive order requiring officials to secure the President’s consent before appearing in inquiries in aid of legislation was invalid in part; executive privilege must be invoked by the President or the Executive Secretary on her authority.', 'Limits of executive privilege.'),
     ('Neri v. Senate Committee on Accountability', 'G.R. No. 180643, March 25, 2008', 'Presidential communications privilege protected an official’s answers to three questions on conversations with the President; the contempt and arrest order was set aside.', 'Presidential communications privilege.')])
n('art-vi-sec-22', 'Heads of departments may appear before either House on their own initiative or upon request; appearances in the question hour are conducted as the rules provide. Unlike Sec. 21, attendance here is discretionary.')
n('art-vi-sec-23', 'Congress, by a vote of two-thirds of both Houses in joint session voting separately, has the sole power to declare a state of war; in times of war or other national emergency it may, by law, authorize the President to exercise powers necessary to carry out a declared national policy, for a limited period and subject to restrictions.', chk=['two-thirds'])
n('art-vi-sec-24', 'Appropriation, revenue and tariff bills, bills authorizing increase of the public debt, bills of local application, and private bills originate exclusively in the House; the Senate may propose or concur with amendments.',
  d=[('Tolentino v. Secretary of Finance', 'G.R. No. 115455, August 25, 1994', 'It is the bill, not the law, that must originate in the House. The Senate may propose a substitute bill once the House bill has been received.', 'What “originate exclusively” means.')])
n('art-vi-sec-25', 'Limits on appropriations: Congress may not increase the President’s budget recommendation; no rider; procedure for approving appropriations for Congress is strictly followed; no transfer of appropriations, but the heads of branches and constitutional bodies may augment items from savings in their own appropriations; and the general appropriations law is automatically re-enacted if not passed.',
  d=[('Araullo v. Aquino III', 'G.R. No. 209287, July 1, 2014', 'Acts under the Disbursement Acceleration Program were unconstitutional: withdrawn unobligated allotments were not “savings”, and cross-border transfers to other branches were prohibited.', 'Savings and augmentation.'),
     ('Belgica v. Ochoa', 'G.R. No. 208566, November 19, 2013', 'The Priority Development Assistance Fund was unconstitutional: post-enactment intervention by legislators in the execution of the budget violates separation of powers and non-delegation.', 'The “pork barrel” case.')])
n('art-vi-sec-26', 'Every bill shall embrace only one subject expressed in its title. No bill becomes law unless it passed three readings on separate days and printed copies in final form were distributed three days before passage, except when the President certifies its immediate enactment to meet a public calamity or emergency.', chk=['three readings', 'three days'])
n('art-vi-sec-27', 'Every bill is presented to the President, who signs it or vetoes it with his objections; Congress overrides the veto by two-thirds of all members of each House. The President may veto particular items of appropriation, revenue or tariff bills. A bill becomes law if he does not act within thirty days of receipt.', chk=['two-thirds', 'thirty days'])
n('art-vi-sec-28', 'Taxation must be uniform and equitable; Congress shall evolve a progressive system. Charitable institutions, churches, parsonages and non-profit cemeteries, and all lands, buildings and improvements actually, directly and exclusively used for religious, charitable or educational purposes, are exempt from taxation. No tax exemption may be granted without the concurrence of a majority of all the members of Congress.',
  t=['Sec. 28(3) exempts from property tax only (real property “actually, directly and exclusively used”), not from income tax.'], chk=['actually, directly, and exclusively'])
n('section-29', 'No money may be paid out of the Treasury except under an appropriation made by law. No public money or property may be applied for the benefit of any religion or religious ministers, except to a priest or minister assigned to the armed forces, a penal institution, a government orphanage or leprosarium. Money collected on a tax levied for a special purpose is treated as a special fund.')
n('section-30', 'No law may increase the appellate jurisdiction of the Supreme Court without its advice and concurrence.',
  d=[('Fabian v. Desierto', 'G.R. No. 129742, September 16, 1998', 'A law providing for direct appeal to the Supreme Court from the Ombudsman in administrative cases was void for increasing the Court’s appellate jurisdiction without its consent; such appeals go to the Court of Appeals.', 'Application of Sec. 30.')])
n('section-32', 'Congress shall provide for a system of initiative and referendum by which the people may directly propose and enact laws or approve or reject any act of Congress or local legislative body, upon a petition of at least ten percent of the registered voters, every district having at least three percent.', t=['RA 6735 implements this for laws and local measures (not for constitutional amendments: Santiago v. COMELEC, 1997).'])

# Article VII — Executive
n('art-vii-sec-2', 'The President must be a natural-born citizen, a registered voter, able to read and write, at least forty years old on election day, and a resident of the Philippines for at least ten years immediately before the election.', chk=['forty years', 'ten years'])
n('art-vii-sec-4', 'The President and Vice-President are elected by direct vote for six years. The President is not eligible for any reelection; the Vice-President may not serve more than two successive terms. The Supreme Court en banc is the sole judge of contests on their election, returns and qualifications.',
  t=['The Supreme Court sits as the Presidential Electoral Tribunal (PET) for these contests.'], chk=['six years'])
n('art-vii-sec-13', 'The President, Vice-President, Cabinet members and their deputies may not hold any other office or employment during their tenure unless the Constitution provides otherwise, nor practise a profession, engage in business or have financial interest in government contracts. The President’s relatives within the fourth degree may not be appointed to certain offices during his tenure.',
  t=['This is stricter than the rule for other public officers (Art. IX-B, Sec. 7): other offices are allowed only if the Constitution itself provides (Civil Liberties Union v. Executive Secretary, 1991). Ex officio positions required by the primary function are not covered.'])
n('art-vii-sec-15', 'Two months before the next presidential election and until the end of his term, a President or Acting President shall not make appointments, except temporary appointments to executive positions when continued vacancies will prejudice public service or endanger public safety.',
  d=[('De Castro v. Judicial and Bar Council', 'G.R. No. 191002, March 17, 2010', 'The ban on midnight appointments does not apply to appointments to the Supreme Court, which Art. VIII, Sec. 4(1) requires to be made within ninety days of a vacancy.', 'Scope of the ban.')], chk=['Two months'])
n('art-vii-sec-16', 'The President nominates and, with the consent of the Commission on Appointments, appoints heads of executive departments, ambassadors, other public ministers and consuls, officers of the armed forces from the rank of colonel or naval captain, and other officers whose appointments are vested in him by the Constitution. Other officers are appointed without that consent.',
  t=['Only the four groups named in the first sentence need confirmation (Sarmiento v. Mison, 1987).', 'Ad interim appointments during recess are effective at once, until disapproved or until the next adjournment of Congress.'])
n('art-vii-sec-17', 'The President has control of all executive departments, bureaus and offices, and shall ensure that the laws are faithfully executed.', t=['Control (the power to alter or set aside a subordinate’s acts) differs from supervision over local governments (Art. X, Sec. 4).'])
n('art-vii-sec-18', 'As Commander-in-Chief, the President may call out the armed forces to prevent or suppress lawless violence, invasion or rebellion; and in case of invasion or rebellion, when public safety requires, may suspend the privilege of the writ of habeas corpus or place the country or part of it under martial law for not more than sixty days. He must report to Congress within forty-eight hours. Congress, voting jointly by a majority of all its members, may revoke it or, at his initiative, extend it. The Supreme Court may review the sufficiency of its factual basis in a proceeding filed by any citizen and must decide within thirty days.',
  t=['Martial law does not suspend the Constitution, supplant civilian courts, or authorize military courts over civilians where civil courts function.', 'The suspension of the privilege applies only to persons judicially charged for rebellion or offenses connected with invasion.'],
  d=[('Lagman v. Medialdea', 'G.R. No. 231658, July 4, 2017', 'Proclamation No. 216 (martial law in Mindanao) was upheld: the Court reviews only whether the President had sufficient factual basis, judged by what he knew at the time.', 'The standard of review under Sec. 18.')],
  chk=['sixty days', 'forty-eight hours', 'thirty days'])
n('art-vii-sec-19', 'Except in impeachment cases or as otherwise provided, the President may grant reprieves, commutations and pardons, and remit fines and forfeitures, after conviction by final judgment; and may grant amnesty with the concurrence of a majority of all the members of Congress.',
  t=['Pardon requires final conviction; amnesty does not.', 'Pardon for election offenses needs COMELEC’s favorable recommendation (Art. IX-C, Sec. 5).'])
n('art-vii-sec-21', 'No treaty or international agreement is valid and effective unless concurred in by at least two-thirds of all the members of the Senate.',
  d=[('Saguisag v. Ochoa', 'G.R. No. 212426, January 12, 2016', 'The Enhanced Defense Cooperation Agreement was a valid executive agreement implementing existing treaties; it did not need Senate concurrence.', 'Treaties versus executive agreements.'),
     ('Pimentel v. Office of the Executive Secretary', 'G.R. No. 158088, July 6, 2005', 'The President has the sole authority to ratify a treaty; courts cannot compel her to transmit a signed treaty to the Senate.', 'Who ratifies.')], chk=['two-thirds'])

# Article VIII — Judicial
n('art-viii-sec-1', 'Judicial power is vested in one Supreme Court and lower courts. It includes the duty to settle actual controversies involving legally demandable and enforceable rights, and to determine whether there has been grave abuse of discretion amounting to lack or excess of jurisdiction on the part of any branch or instrumentality of the government.',
  t=['The second clause is the “expanded” certiorari jurisdiction, adopted to limit the political question doctrine.', 'Judicial review needs an actual case, standing, earliest opportunity, and the constitutional question as the lis mota.'])
n('art-viii-sec-4', 'The Supreme Court is composed of a Chief Justice and fourteen Associate Justices, sitting en banc or in divisions of three, five or seven. Cases on the constitutionality of a treaty, international or executive agreement, or law are heard en banc and decided by a majority of the members who actually took part and voted.', chk=['fourteen Associate Justices'])
n('art-viii-sec-5', 'Powers of the Supreme Court: original jurisdiction over cases affecting ambassadors, other public ministers and consuls, and petitions for certiorari, prohibition, mandamus, quo warranto and habeas corpus; review of judgments of lower courts in specified cases; temporary assignment of judges; change of venue; rule-making on pleading, practice and procedure, admission to the practice of law, the Integrated Bar and legal assistance; and appointment of court officials.',
  t=['Rules of procedure must not diminish, increase or modify substantive rights.'],
  d=[('Estipona v. Lobrigo', 'G.R. No. 226679, August 15, 2017', 'Section 23 of RA 9165, which barred plea bargaining in drug cases, was unconstitutional: plea bargaining is a rule of procedure within the Court’s exclusive rule-making power.', 'Congress cannot legislate procedure.')])
n('art-viii-sec-7', 'A member of the Supreme Court must be a natural-born citizen, at least forty years old, and must have been for fifteen years or more a judge of a lower court or engaged in the practice of law. Members of the judiciary must be of proven competence, integrity, probity and independence.', chk=['forty years', 'fifteen years'])
n('art-viii-sec-9', 'Members of the Supreme Court and judges of lower courts are appointed by the President from a list of at least three nominees prepared by the Judicial and Bar Council for every vacancy, within ninety days from submission of the list for lower courts.', chk=['ninety days'])
n('art-viii-sec-11', 'Justices and judges hold office during good behavior until seventy years old or incapacity. The Supreme Court en banc may discipline judges of lower courts or order their dismissal by a majority of the members who actually took part and voted.', t=['Justices of the Supreme Court are removed only by impeachment (Art. XI, Sec. 2).'], chk=['seventy years'])
n('art-viii-sec-12', 'Members of the Supreme Court and other courts may not be designated to any agency performing quasi-judicial or administrative functions.', d=[('In re: Manzano', 'A.M. No. 88-7-1861-RTC, October 5, 1988', 'A judge could not serve as a member of a provincial committee on justice, an administrative body, consistent with the separation of powers.', 'Judges and administrative work.')])
n('art-viii-sec-14', 'No decision shall be rendered without expressing clearly and distinctly the facts and the law on which it is based. No petition for review or motion for reconsideration may be refused due course or denied without stating the legal basis.', t=['Minute resolutions denying petitions for review are allowed: they adopt the findings below and state the basis briefly.'])
n('art-viii-sec-15', 'Cases must be decided within twenty-four months from submission in the Supreme Court; twelve months in lower collegiate courts, unless reduced by the Supreme Court; and three months in all other lower courts.', chk=['twenty-four months', 'twelve months', 'three months'])

# Article IX — Constitutional Commissions
n('art-ix-sec-1', 'The Constitutional Commissions — the Civil Service Commission, the Commission on Elections and the Commission on Audit — are independent.')
n('art-ix-sec-5', 'The Commissions enjoy fiscal autonomy: their approved annual appropriations are automatically and regularly released.')
n('art-ix-sec-7', 'Each Commission decides by a majority vote of all its members any case or matter before it within sixty days from submission. Unless provided otherwise, its decisions may be brought to the Supreme Court on certiorari within thirty days from receipt of a copy.',
  t=['The remedy is certiorari under Rule 64 (in relation to Rule 65), not an appeal.', 'COMELEC decisions in division must first be reviewed en banc before going to the Supreme Court.'], chk=['sixty days', 'thirty days'])
n('art-ix-sec-2-2', 'The civil service embraces all branches, subdivisions, instrumentalities and agencies of the Government, including GOCCs with original charters. Appointments are made according to merit and fitness, determined as far as practicable by competitive examination, except for positions that are policy-determining, primarily confidential or highly technical. No officer or employee may be removed or suspended except for cause provided by law. Civil servants may not engage in electioneering or partisan political campaigns, and have the right to self-organization.',
  t=['GOCCs without original charters (incorporated under the Corporation Code) are not in the civil service; their employees are under the Labor Code.'], chk=['original charters'])
n('art-ix-sec-6-2', 'No candidate who lost in an election may, within one year after it, be appointed to any office in the Government or GOCCs.', chk=['one year'])
n('art-ix-sec-7-2', 'No elective official may be appointed or designated to any public office during his tenure. Unless allowed by law or by the primary functions of his position, no appointive official may hold any other office.')
n('art-ix-sec-8-2', 'No public officer or employee may receive additional, double or indirect compensation unless specifically authorized by law, nor accept any present, emolument, office or title from a foreign government without the consent of Congress. Pensions and gratuities are not additional compensation.')
n('art-ix-sec-2-3', 'Powers of the COMELEC: enforce and administer election laws; exclusive original jurisdiction over contests on the election of regional, provincial and city officials, and appellate jurisdiction over contests of municipal and barangay officials decided by trial courts; decide all questions affecting elections except the right to vote; deputize law enforcement agencies; register parties; file petitions to include or exclude voters; investigate and prosecute election offenses; recommend measures to Congress; and recommend sanctions against its deputies.',
  t=['Its decisions in contests involving municipal and barangay officials are final, executory and not appealable, but still open to certiorari.', 'The power to prosecute election offenses is now concurrent with the DOJ prosecutors (RA 9369).'])
n('art-ix-sec-5-3', 'No pardon, amnesty, parole or suspension of sentence for violation of election laws may be granted by the President without the favorable recommendation of the COMELEC.')
n('art-ix-sec-9', 'Unless the COMELEC fixes otherwise in special cases, the election period begins ninety days before election day and ends thirty days after.', chk=['ninety days', 'thirty days'])
n('art-ix-sec-2-4', 'The Commission on Audit examines, audits and settles all accounts on the revenue and receipts of, and expenditures or uses of funds and property owned or held in trust by, the Government, including GOCCs with original charters, and on a post-audit basis entities with fiscal autonomy and non-governmental entities receiving subsidies. It has exclusive authority to define the scope of its audit and to promulgate accounting and auditing rules.')
n('art-ix-sec-3-4', 'No law may exempt any entity of the Government or its subsidiaries, or any investment of public funds, from the jurisdiction of the Commission on Audit.')

# Article X — Local Government
n('art-x-sec-2', 'Territorial and political subdivisions enjoy local autonomy.', t=['Autonomy means decentralization of administration, not of power, for ordinary LGUs; autonomous regions enjoy political autonomy.'])
n('art-x-sec-4', 'The President exercises general supervision over local governments.', d=[('Pimentel v. Aguirre', 'G.R. No. 132988, July 19, 2000', 'An order withholding part of the LGUs’ internal revenue allotments was invalid: supervision means seeing that local governments act within the law, not controlling them.', 'Supervision, not control.')])
n('art-x-sec-5', 'Each local government unit has the power to create its own sources of revenue and to levy taxes, fees and charges, subject to guidelines and limits Congress provides, consistent with local autonomy.')
n('art-x-sec-6', 'LGUs have a just share, as determined by law, in the national taxes, automatically released to them.', d=[('Mandanas v. Ochoa', 'G.R. No. 199802, July 3, 2018', 'The LGUs’ share must be computed on all national taxes, not only national internal revenue taxes as the Local Government Code’s wording had been applied; the base includes customs duties and other national taxes.', 'The “Mandanas ruling” on the just share.')])
n('art-x-sec-8', 'The term of elective local officials, except barangay officials, is three years, and no official may serve more than three consecutive terms. Voluntary renunciation of office for any length of time is not an interruption.',
  t=['An involuntary loss of office (e.g., losing an election protest before the term ends) can interrupt; preventive suspension does not (Aldovino v. COMELEC, 2009).'], chk=['three years', 'three consecutive terms'])
n('art-x-sec-10', 'No province, city, municipality or barangay may be created, divided, merged, abolished or its boundary substantially altered except under the criteria in the Local Government Code and with the approval of a majority of the votes cast in a plebiscite in the political units directly affected.')

# Article XI — Accountability
n('art-xi-sec-1', 'Public office is a public trust. Public officers and employees must at all times be accountable to the people, serve them with utmost responsibility, integrity, loyalty and efficiency, act with patriotism and justice, and lead modest lives.')
n('art-xi-sec-2', 'The President, the Vice-President, the Members of the Supreme Court, the Members of the Constitutional Commissions and the Ombudsman may be removed by impeachment for culpable violation of the Constitution, treason, bribery, graft and corruption, other high crimes, or betrayal of public trust. Other officers may be removed as provided by law, but not by impeachment.')
n('art-xi-sec-3', 'The House has the exclusive power to initiate impeachment: a verified complaint by a member, or by a citizen with a member’s endorsement; a vote of at least one-third of all its members impeaches. No impeachment proceeding may be initiated against the same official more than once within a period of one year. The Senate has the sole power to try and decide; conviction needs two-thirds of all its members. Judgment extends only to removal from office and disqualification, but the convicted official remains liable to prosecution.',
  t=['Proceedings are “initiated” when a complaint is filed and referred to the House Committee on Justice (Francisco v. House of Representatives, 2003).', 'When the President is on trial, the Chief Justice presides but does not vote.'],
  chk=['one-third', 'two-thirds', 'one year'])
n('art-xi-sec-12', 'The Ombudsman and his Deputies, as protectors of the people, shall act promptly on complaints against public officials and employees, including those of GOCCs, and notify the complainants of the action taken.')
n('art-xi-sec-13', 'Powers of the Ombudsman: investigate any act or omission of a public official that appears illegal, unjust, improper or inefficient; direct officials to perform their duties; direct the officer concerned to take action against an erring official (including removal, suspension and other sanctions) and ensure compliance; request assistance; audit through COA; publicize matters; and recommend measures.',
  t=['The Ombudsman’s power to impose administrative penalties is mandatory, not merely recommendatory (Office of the Ombudsman v. Masing, 2008).'])
n('art-xi-sec-15', 'The State’s right to recover properties unlawfully acquired by public officials or employees from them or their nominees or transferees is not barred by prescription, laches or estoppel.', t=['This applies to civil actions for recovery of ill-gotten wealth, not to criminal prosecution (Presidential Ad Hoc Fact-Finding Committee v. Desierto, 1999).'])
