def main():
    d = json.load(open(f'{SITE}/codes/const1987.json'))
    by = {p['i']: p for p in d['provisions']}
    errs = []
    for pid, (e, chk) in N.items():
        if pid not in by:
            errs.append('no provision ' + pid); continue
        text = ' '.join(x for x in by[pid]['p'] if isinstance(x, str)).replace('’', "'").lower()
        for c in chk:
            if c.lower() not in text:
                errs.append(f'{pid}: “{c}” not in the text')
    if errs:
        raise SystemExit('\n'.join(errs))
    cur = json.load(open(f'{SITE}/notes/const1987.json'))
    for pid, (e, _) in N.items():
        cur[pid] = {**cur.get(pid, {}), **e}
    json.dump(cur, open(f'{SITE}/notes/const1987.json', 'w'), ensure_ascii=False, separators=(',', ':'))
    print('Constitution notes added:', len(N), '| total:', len(cur))


if __name__ == '__main__':
    main()
